import { Injectable } from '@angular/core';
import { LocationStrategy } from '@angular/common';
import { PlatformLocation } from '@angular/common';
import { BehaviorSubject } from 'rxjs';

@Injectable()
export class GwtHashLocationStrategy implements LocationStrategy {
  private _subject = new BehaviorSubject<PopStateEvent | null>(null);
  constructor(private _platformLocation: PlatformLocation) {
    this._platformLocation.onPopState((e: PopStateEvent) => this._subject.next(e));
    this._platformLocation.onHashChange((e: HashChangeEvent) => this._subject.next(e as any));
  }
  onPopState(fn: (event: PopStateEvent) => void): void {
    this._subject.subscribe((event) => { if (event) fn(event); });
  }
  getBaseHref(): string { return this._platformLocation.getBaseHrefFromDOM() || '/'; }
  path(includeHash: boolean = false): string {
    const search = this._platformLocation.href;
    const hashIndex = search.indexOf('#');
    let path = hashIndex >= 0 ? search.substring(hashIndex + 1) : '';
    if (path.startsWith('/')) path = path.substring(1);
    // remove query? GWT no query. If path contains ? maybe split.
    const queryIndex = path.indexOf('?');
    if (queryIndex >= 0) path = path.substring(0, queryIndex);
    return '/' + path; // internal always leading slash
  }
  prepareExternalUrl(internal: string, search: string): string {
    // internal e.g. /manufacturer, search maybe ''
    let hash = internal.startsWith('/') ? internal.substring(1) : internal;
    if (search) hash += search; // search includes ?
    return '#' + hash;
  }
  pushState(state: any, url: string, title: string): void {
    const external = this.prepareExternalUrl(url, '');
    this._platformLocation.pushState(state, external, title);
    this._subject.next(new PopStateEvent('popstate', { state }));
  }
  replaceState(state: any, url: string, title: string): void { ... }
  forward/back: platformLocation.forward/back
  getState(): any { return this._platformLocation.getState(); }
}
```
