```
import { Injectable } from '@angular/core';
import { LocationStrategy, PlatformLocation } from '@angular/common';
import { BehaviorSubject } from 'rxjs';

@Injectable()
export class GwtHashLocationStrategy implements LocationStrategy {
  private readonly _subject = new BehaviorSubject<PopStateEvent | null>(null);

  constructor(private readonly _platformLocation: PlatformLocation) {
    this._platformLocation.onPopState((event: PopStateEvent) => this._subject.next(event));
    this._platformLocation.onHashChange((event: HashChangeEvent) => {
      this._subject.next(new PopStateEvent('popstate', { state: event.newURL }));
    });
  }

  onPopState(fn: (event: PopStateEvent) => void): void {
    this._subject.subscribe((event) => {
      if (event) {
        fn(event);
      }
    });
  }

  getBaseHref(): string {
    return this._platformLocation.getBaseHrefFromDOM() || '/';
  }

  path(includeHash: boolean = false): string {
    const href = this._platformLocation.href;
    const hashIndex = href.indexOf('#');
    let hash = hashIndex >= 0 ? href.substring(hashIndex + 1) : '';
    // Remove leading slash if present to tolerate #/manufacturer.
    if (hash.startsWith('/')) {
      hash = hash.substring(1);
    }
    const queryIndex = hash.indexOf('?');
    if (queryIndex >= 0) {
      hash = hash.substring(0, queryIndex);
    }
    return '/' + hash;
  }

  prepareExternalUrl(internal: string, search: string): string {
    let hash = internal.startsWith('/') ? internal.substring(1) : internal;
    if (search) {
      hash += search;
    }
    return '#' + hash;
  }

  pushState(state: any, url: string, title: string): void {
    const external = this.prepareExternalUrl(url, '');
    this._platformLocation.pushState(state, title ?? '', external);
    this._subject.next(new PopStateEvent('popstate', { state }));
  }

  replaceState(state: any, url: string, title: string): void {
    const external = this.prepareExternalUrl(url, '');
    this._platformLocation.replaceState(state, title ?? '', external);
    this._subject.next(new PopStateEvent('popstate', { state }));
  }

  forward(): void { this._platformLocation.forward(); }
  back(): void { this._platformLocation.back(); }
  getState(): any { return this._platformLocation.getState(); }
}
```

