```
import { Injectable } from '@angular/core';
import { LocationStrategy } from '@angular/common';
import { BehaviorSubject } from 'rxjs';

@Injectable()
export class GwtHashLocationStrategy implements LocationStrategy {
  private readonly _subject = new BehaviorSubject<PopStateEvent | null>(null);

  constructor() {
    if (typeof window !== 'undefined') {
      window.addEventListener('popstate', (event: PopStateEvent) => this._subject.next(event));
      window.addEventListener('hashchange', () => this._subject.next(new PopStateEvent('popstate', { state: null })));
    }
  }

  onPopState(fn: (event: PopStateEvent) => void): void {
    this._subject.subscribe((event) => { if (event) fn(event); });
  }

  getBaseHref(): string {
    if (typeof document === 'undefined') return '';
    return document.querySelector('base')?.getAttribute('href') ?? '';
  }

  path(includeHash: boolean = false): string {
    if (typeof window === 'undefined') return '/';
    const hash = window.location.hash;
    let internal = hash.startsWith('#') ? hash.substring(1) : hash;
    if (internal.startsWith('/')) internal = internal.substring(1);
    const queryIndex = internal.indexOf('?');
    if (queryIndex >= 0) internal = internal.substring(0, queryIndex);
    const result = '/' + internal;
    return includeHash ? window.location.hash : result;
  }

  prepareExternalUrl(internal: string, search: string = ''): string {
    let hash = internal.startsWith('/') ? internal.substring(1) : internal;
    if (search) hash += search;
    return '#' + hash;
  }

  pushState(state: any, url: string, title: string): void {
    if (typeof window === 'undefined') return;
    const external = this.prepareExternalUrl(url, '');
    window.history.pushState(state, title ?? '', external);
    this._subject.next(new PopStateEvent('popstate', { state }));
  }

  replaceState(state: any, url: string, title: string): void {
    if (typeof window === 'undefined') return;
    const external = this.prepareExternalUrl(url, '');
    window.history.replaceState(state, title ?? '', external);
    this._subject.next(new PopStateEvent('popstate', { state }));
  }

  forward(): void { if (typeof window !== 'undefined') window.history.forward(); }
  back(): void { if (typeof window !== 'undefined') window.history.back(); }
  getState(): any { return typeof window !== 'undefined' ? window.history.state : null; }
}
